/* UNIT 4 ASSIGNMENTS (4.1 to 4.11): Booleans, logic, comparisons, if/elif/else, key events, loops, random. Real companies, real jobs, no code shown. */
"use strict";
const { V, FN, note, S, X, ASG, def } = require("./asg-kit.js");
const PR = (s) => new RegExp("print\\(.*" + s);
const FOR = (hdr) => new RegExp("^\\s*for\\s+\\w+\\s+in\\s+" + hdr + "\\s*:", "m");

/* ---------------------------------------------------------------- 4.1 */
def("u4l1", "Instagram Account Flags", ["**You are an engineer on the Instagram accounts team.** Every account has a handful of yes or no facts (Booleans), and many features switch on or off by comparing a number, such as the follower count, with a limit."],
  ["True and False", "comparisons make Booleans", "storing a comparison", "= stores and == asks", "not"], [
  S("Store the account", ["Make three variables for one account: **`is_verified`** (`True`), **`is_private`** (`False`) and **`followers`** (`12500`, a whole number)."],
    "Make the three variables.", `is_verified = True\nis_private = False\nfollowers = 12500`,
    [["is_verified is True", V("is_verified", "True\\s*$")], ["is_private is False", V("is_private", "False\\s*$")], ["followers is 12500", V("followers", "12500")]],
    "Nothing prints yet."),
  S("Comparisons make Booleans", ["Print `Over 10000:` followed by the **comparison** of the followers with `10000`, and `Under 1000:` followed by the comparison with `1000`. Do not type True or False yourself: let Python answer."],
    "Print the two comparisons.", `print("Over 10000:", followers > 10000)\nprint("Under 1000:", followers < 1000)`,
    [["a comparison with >", /print\(\s*["']Over 10000:["']\s*,\s*followers\s*>\s*10000\s*\)/], ["a comparison with <", /print\(\s*["']Under 1000:["']\s*,\s*followers\s*<\s*1000\s*\)/]],
    "Run it.", [["Over 10000: True", /Over 10000: True/], ["Under 1000: False", /Under 1000: False/]]),
  S("Save a comparison", ["Instagram lets an account go live at `1000` followers or more, and calls an account **mega** above `1000000` followers. Store those answers in **`can_go_live`** and **`is_mega`**, then print `Can go live:` and `Mega:` with each."],
    "Store both comparisons and print them.", `can_go_live = followers >= 1000\nis_mega = followers > 1000000\nprint("Can go live:", can_go_live)\nprint("Mega:", is_mega)`,
    [["can_go_live compares followers with 1000", /^\s*can_go_live\s*=\s*followers\s*>=\s*1000/m], ["is_mega compares followers with 1000000", /^\s*is_mega\s*=\s*followers\s*>\s*1000000/m]],
    "Run it.", [["Can go live: True", /Can go live: True/], ["Mega: False", /Mega: False/]]),
  S("One equals or two", ["A post has **`likes`** equal to `250`. Print `Hit 250:` followed by whether the likes **equal** 250, and `Hit 300:` followed by whether they equal 300. Then add a comment that starts with `# EQUALS:` and explains in at least ten words the difference between one equals sign and two."],
    "Store the likes, print and write the comment.", `likes = 250\nprint("Hit 250:", likes == 250)\nprint("Hit 300:", likes == 300)\n# EQUALS: one equals sign stores a value in a variable but two equals signs ask whether two values are the same`,
    [["likes is 250", V("likes", "250")], ["comparing likes with == 250", /likes\s*==\s*250/], ["comparing likes with == 300", /likes\s*==\s*300/], ["an EQUALS comment of ten or more words", note("EQUALS", 10), 1, "comments"]],
    "Run it.", [["Hit 250: True", /Hit 250: True/], ["Hit 300: False", /Hit 300: False/]]),
  S("Flip it with not", ["Print `Public account:` followed by the **opposite** of `is_private`, and `Not verified:` followed by the opposite of `is_verified`, using the word that flips a Boolean."],
    "Print the two flipped values.", `print("Public account:", not is_private)\nprint("Not verified:", not is_verified)`,
    [["not applied to is_private", /print\(\s*["']Public account:["']\s*,\s*not\s+is_private\s*\)/], ["not applied to is_verified", /print\(\s*["']Not verified:["']\s*,\s*not\s+is_verified\s*\)/]],
    "Run it.", [["Public account: True", /Public account: True/], ["Not verified: False", /Not verified: False/]])]);

/* ---------------------------------------------------------------- 4.2 */
def("u4l2", "Disney+ Access Rules", ["**You are on the Disney+ accounts team.** Whether a viewer can stream, gets a discount or lands on a kid profile is decided by combining Booleans with **and**, **or** and **not**. Disney World's ride gates use the same logic."],
  ["and", "or", "not", "combining comparisons", "is it in a range", "which operator goes first"], [
  S("The viewer", ["Make five variables: **`has_subscription`** (`True`), **`payment_failed`** (`False`), **`age`** (`15`), **`is_student`** (`True`) and **`is_military`** (`False`)."],
    "Make the five variables.", `has_subscription = True\npayment_failed = False\nage = 15\nis_student = True\nis_military = False`,
    [["has_subscription is True", V("has_subscription", "True")], ["payment_failed is False", V("payment_failed", "False")], ["age is 15", V("age", "15")], ["is_student is True", V("is_student", "True")], ["is_military is False", V("is_military", "False")]],
    "Nothing prints yet."),
  S("Can they stream", ["A viewer can stream when they have a subscription **and** their payment has **not** failed. Store that in **`can_stream`** and print `Can stream:` followed by it."],
    "Store the rule and print it.", `can_stream = has_subscription and not payment_failed\nprint("Can stream:", can_stream)`,
    [["can_stream uses and with not", /^\s*can_stream\s*=\s*has_subscription\s+and\s+not\s+payment_failed/m]],
    "Run it.", [["Can stream: True", /Can stream: True/]]),
  S("The discount and the profile", ["Students **or** military members get a discount: store it in **`gets_discount`**. A **teen profile** is for viewers who are at least `13` **and** at most `17`: store it in **`teen_profile`** with one expression that checks both ends of the range. Print `Discount:` and `Teen profile:` with each."],
    "Store both rules and print them.", `gets_discount = is_student or is_military\nteen_profile = age >= 13 and age <= 17\nprint("Discount:", gets_discount)\nprint("Teen profile:", teen_profile)`,
    [["gets_discount uses or", /^\s*gets_discount\s*=\s*is_student\s+or\s+is_military/m], ["teen_profile checks both ends of the range", /^\s*teen_profile\s*=\s*age\s*>=\s*13\s+and\s+age\s*<=\s*17/m]],
    "Run it.", [["Discount: True", /Discount: True/], ["Teen profile: True", /Teen profile: True/]]),
  S("Which goes first", ["Print `Rule A:` followed by `True or False and False`, and `Rule B:` followed by the same three values with **parentheses** around `True or False` so the **or** goes first. Then add a comment that starts with `# FIRST:` and says in at least eight words which operator Python does first when there are no parentheses."],
    "Print both rules and write the comment.", `print("Rule A:", True or False and False)\nprint("Rule B:", (True or False) and False)\n# FIRST: Python does the and before the or unless parentheses change the order`,
    [["Rule A without parentheses", /print\(\s*["']Rule A:["']\s*,\s*True\s+or\s+False\s+and\s+False\s*\)/], ["Rule B with parentheses", /print\(\s*["']Rule B:["']\s*,\s*\(\s*True\s+or\s+False\s*\)\s+and\s+False\s*\)/], ["a FIRST comment of eight or more words", note("FIRST", 8), 1, "comments"]],
    "Run it.", [["Rule A: True", /Rule A: True/], ["Rule B: False", /Rule B: False/]]),
  S("The ride gate", ["At Disney World a rider must be at least `40` inches tall **and** have a ticket to ride, and anyone under `48` inches **or** under `10` years old needs an adult. Ask `Height in inches: ` as a whole number in **`height`**, make **`has_ticket`** equal to `True`, and print `Can ride:` and `Needs adult:` followed by each rule (use the age variable from earlier)."],
    "Ask, decide and print.", `height = int(input("Height in inches: "))\nhas_ticket = True\nprint("Can ride:", height >= 40 and has_ticket)\nprint("Needs adult:", height < 48 or age < 10)`,
    [["height is a whole number from input", /^\s*height\s*=\s*int\(\s*input\(/m], ["has_ticket is True", V("has_ticket", "True")], ["a ride rule with and", /print\(\s*["']Can ride:["']\s*,\s*height\s*>=\s*40\s+and\s+has_ticket\s*\)/], ["an adult rule with or", /print\(\s*["']Needs adult:["']\s*,\s*height\s*<\s*48\s+or\s+age\s*<\s*10\s*\)/]],
    "Run it and type 44.", [["Can ride: True", /Can ride: True/], ["Needs adult: True", /Needs adult: True/]])],
  [{ answers: [["Height", "44"]] }]);

