def("u4l3", "Wordle Guess Checker", ["**You are an engineer at The New York Times, which publishes Wordle.** Every guess a player types is checked against the secret word, the number of tries and the streak, all with the six comparison operators."],
  ["==", "!=", "<  >  <=  >=", "the boundary", "math inside a comparison", "comparing text and case"], [
  S("Check the guess", ["Make **`secret`** equal to `crane`. Ask `Guess: ` and store the answer in **`guess`**. Print `Correct:` followed by whether the guess **equals** the secret, and `Different:` followed by whether it does **not** equal the secret."],
    "Ask, compare and print.", `secret = "crane"\nguess = input("Guess: ")\nprint("Correct:", guess == secret)\nprint("Different:", guess != secret)`,
    [["secret is crane", V("secret", "[\"']crane[\"']")], ["guess comes from input", /^\s*guess\s*=\s*input\(/m], ["an equals comparison", /print\(\s*["']Correct:["']\s*,\s*guess\s*==\s*secret\s*\)/], ["a not-equals comparison", /print\(\s*["']Different:["']\s*,\s*guess\s*!=\s*secret\s*\)/]],
    "Run it and type crane.", [["Correct: True", /Correct: True/], ["Different: False", /Different: False/]]),
  S("Tries", ["A player has used **`attempts`** `4` of **`max_attempts`** `6`. Print four lines: `Under limit:` (attempts less than the max), `At limit:` (attempts greater than **or equal to** the max), `Over limit:` (attempts greater than the max) and `Within limit:` (attempts less than **or equal to** the max)."],
    "Store the numbers and print the four comparisons.", `attempts = 4\nmax_attempts = 6\nprint("Under limit:", attempts < max_attempts)\nprint("At limit:", attempts >= max_attempts)\nprint("Over limit:", attempts > max_attempts)\nprint("Within limit:", attempts <= max_attempts)`,
    [["attempts is 4", V("attempts", "4")], ["max_attempts is 6", V("max_attempts", "6")], ["a less-than comparison", /attempts\s*<\s*max_attempts/], ["a greater-or-equal comparison", /attempts\s*>=\s*max_attempts/], ["a greater-than comparison", /attempts\s*>\s*max_attempts/], ["a less-or-equal comparison", /attempts\s*<=\s*max_attempts/]],
    "Run it.", [["Under limit: True", /Under limit: True/], ["At limit: False", /At limit: False/], ["Over limit: False", /Over limit: False/], ["Within limit: True", /Within limit: True/]]),
  S("The boundary", ["A guess must have exactly `5` letters. Print `Valid length:` followed by whether the **length** of `guess` equals 5. A player also gets a **streak badge** at `7` days or more: make **`streak`** equal to `7` and print `Badge:` followed by whether the streak is at least 7 (this is the classic boundary: the number 7 itself must count)."],
    "Print both checks.", `print("Valid length:", len(guess) == 5)\nstreak = 7\nprint("Badge:", streak >= 7)`,
    [["checking the length of guess", /print\(\s*["']Valid length:["']\s*,\s*len\(\s*guess\s*\)\s*==\s*5\s*\)/], ["streak is 7", V("streak", "7\\s*$")], ["the badge check includes 7", /print\(\s*["']Badge:["']\s*,\s*streak\s*>=\s*7\s*\)/]],
    "Run it.", [["Valid length: True", /Valid length: True/], ["Badge: True", /Badge: True/]]),
  S("Math inside a comparison", ["The streak page asks three questions. Print `Odd streak:` (does the remainder of the streak divided by 2 equal 1), `Divisible by 7:` (does the remainder of the streak divided by 7 equal 0) and `Double beats 10:` (is the streak times 2 greater than 10)."],
    "Print the three comparisons.", `print("Odd streak:", streak % 2 == 1)\nprint("Divisible by 7:", streak % 7 == 0)\nprint("Double beats 10:", streak * 2 > 10)`,
    [["an odd check with %", /streak\s*%\s*2\s*==\s*1/], ["a divisibility check", /streak\s*%\s*7\s*==\s*0/], ["math inside a greater-than", /streak\s*\*\s*2\s*>\s*10/]],
    "Run it.", [["Odd streak: True", /Odd streak: True/], ["Divisible by 7: True", /Divisible by 7: True/], ["Double beats 10: True", /Double beats 10: True/]]),
  S("Case matters", ["Wordle answers are lowercase. Print `Case matters:` followed by whether the text `crane` **equals** the text `Crane`, and `Not the same word:` followed by whether `crane` is **not equal** to `crate`."],
    "Print the two text comparisons.", `print("Case matters:", "crane" == "Crane")\nprint("Not the same word:", "crane" != "crate")`,
    [["comparing crane with Crane", /["']crane["']\s*==\s*["']Crane["']/], ["comparing crane with crate", /["']crane["']\s*!=\s*["']crate["']/]],
    "Run it.", [["Case matters: False", /Case matters: False/], ["Not the same word: True", /Not the same word: True/]])],
  [{ answers: [["Guess", "crane"]] }]);

